<p class="admin-records-note"><?= (int)$total ?> matching transaction<?= $total===1?'':'s' ?>.</p><p class="admin-records-note">All timestamps are in Philippine Standard Time (UTC+8).</p><div class="table-wrap"><table class="admin-record-table payment-table"><colgroup><col style="width:20%"><col style="width:10%"><col style="width:16%"><col style="width:12%"><col style="width:10%"><col style="width:14%"><col style="width:10%"><col style="width:8%"></colgroup><thead><tr><th>Student Name / ID</th><th>Reservation No.</th><th>Transaction Ref.</th><th>Payment Method</th><th>Amount</th><th>Transaction Date</th><th>Payment Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $payment): $reference=(string)$payment['transaction_reference']; $short=mb_strlen($reference)>15?mb_substr($reference,0,8).'…'.mb_substr($reference,-4):$reference; $date=(new DateTimeImmutable($payment['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(config('Booking')->timezone)); $method=['gcash'=>'GCash','card'=>'Card','bank_transfer'=>'Bank Transfer'][$payment['payment_method']]??$payment['payment_method']; ?><tr><td><?= esc($payment['full_name']) ?><small><?= esc($payment['student_id']) ?></small></td><td>#<?= (int)$payment['reservation_id'] ?></td><td><div class="reference-cell"><span title="<?= esc($reference,'attr') ?>" aria-label="<?= esc($reference,'attr') ?>"><?= esc($short) ?></span><button class="record-icon copy-reference" type="button" data-reference="<?= esc($reference,'attr') ?>" aria-label="Copy full transaction reference" title="Copy full reference"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span></button><span class="copy-feedback" role="status" aria-live="polite"></span></div></td><td><span class="category-badge <?= esc($payment['payment_method'],'attr') ?>"><?= esc($method) ?></span></td><td><?= $payment['currency']==='PHP'?'₱':esc($payment['currency']).' ' ?><?= esc(number_format((float)$payment['amount'],2)) ?></td><td title="<?= esc($payment['created_at'],'attr') ?> UTC"><?= esc($date->format('M j, Y')) ?><small><?= esc($date->format('g:i A')) ?></small></td><td><span class="status-badge <?= esc($payment['payment_status'],'attr') ?>"><?= esc(ucfirst($payment['payment_status'])) ?></span></td><td><?php if(!in_array($payment['payment_status'],['pending','failed'],true)): ?><a class="receipt-action" aria-label="View Receipt" title="View Receipt" href="<?= site_url('admin/payments/'.$payment['id'].'/receipt') ?>"><span class="material-symbols-outlined" aria-hidden="true">receipt_long</span></a><?php else: ?><span class="muted-dash">—</span><?php endif ?></td></tr><?php endforeach ?><?php if(!$payments): ?><tr><td colspan="8">No payment transactions match.</td></tr><?php endif ?></tbody></table></div><?= $pager ?>
